/**
 * Managed-automation envelope slices by provider delivery id (plan 0002
 * G2), recorded at hosted admission so channel code running the delivery's
 * task (or session turn) can attach the customer's MCP servers through the
 * control-plane relay. In-memory and TTL-bounded like the hosted pending-
 * send table: the envelope slice carries names only (never credentials)
 * and evaporates with the process.
 *
 * A leaf module (protocol type import only) so product channels can read
 * it without pulling the hosted-delivery route — and its session-engine
 * dependency graph — into their bundles.
 *
 * INTERNAL: first-party multi-tenant deployment plumbing. It ships because
 * the published hosted-delivery runtime imports it; it is not an exported
 * package subpath.
 */
/**
 * Process-wide slot for the table. Hosted engines run the compiled CLI
 * (`dist/`), which records at admission, while first-party factory agents
 * relative-import this file from `src/` and read at finalize — two module
 * instances in one process. A module-local Map would be recorded in one
 * copy and read from the other (always undefined, so a fork never sees its
 * Slack channels or MCP servers); the shared symbol keeps one table.
 */
const MANAGED_AUTOMATION_TABLE_KEY = Symbol.for("cursor.agentkit.hostedManagedAutomationByDelivery");
function managedAutomationTable() {
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- a symbol slot on globalThis is shared by every copy of this module
    const slots = globalThis;
    let table = slots[MANAGED_AUTOMATION_TABLE_KEY];
    if (table === undefined) {
        table = new Map();
        slots[MANAGED_AUTOMATION_TABLE_KEY] = table;
    }
    return table;
}
/** Long enough to outlive a slow review run kicked off by the delivery. */
const MANAGED_AUTOMATION_TTL_MS = 60 * 60_000;
const MANAGED_AUTOMATION_MAX_ENTRIES = 10_000;
export function recordHostedManagedAutomation(delivery) {
    if (delivery.managedAutomation === undefined) {
        console.info(`[bdk] hosted managedAutomation not recorded deliveryId=${delivery.deliveryId}: admission envelope carried no managedAutomation slice (non-managed delivery, or the control plane resolved no MCP servers and no Slack channels)`);
        return;
    }
    const managedAutomationByDelivery = managedAutomationTable();
    const now = Date.now();
    for (const [key, entry] of managedAutomationByDelivery) {
        if (entry.expiresAt <= now) {
            managedAutomationByDelivery.delete(key);
        }
    }
    if (managedAutomationByDelivery.size >= MANAGED_AUTOMATION_MAX_ENTRIES) {
        console.info(`[bdk] hosted managedAutomation table full (${String(managedAutomationByDelivery.size)} entries); clearing before recording deliveryId=${delivery.deliveryId}`);
        managedAutomationByDelivery.clear();
    }
    managedAutomationByDelivery.set(delivery.deliveryId, {
        managedAutomation: delivery.managedAutomation,
        expiresAt: now + MANAGED_AUTOMATION_TTL_MS,
    });
    const slackChannels = delivery.managedAutomation.slackChannels;
    console.info(`[bdk] hosted managedAutomation recorded deliveryId=${delivery.deliveryId} automationUuid=${delivery.managedAutomation.automationUuid} mcpServerNames=${String(delivery.managedAutomation.mcpServerNames.length)} slackChannels=${slackChannels === undefined ? "<absent>" : JSON.stringify(slackChannels)} ttlMs=${String(MANAGED_AUTOMATION_TTL_MS)} tableSize=${String(managedAutomationByDelivery.size)}`);
}
/**
 * The managed automation the control plane attributed to a hosted delivery,
 * when the envelope carried one. Undefined for non-managed deliveries,
 * expired entries, and non-hosted (webhook/stream) dispatch paths.
 */
export function getHostedManagedAutomation(deliveryId) {
    const managedAutomationByDelivery = managedAutomationTable();
    const entry = managedAutomationByDelivery.get(deliveryId);
    if (entry === undefined) {
        console.info(`[bdk] hosted managedAutomation lookup miss deliveryId=${deliveryId}: no entry (never recorded in this process, or evicted) tableSize=${String(managedAutomationByDelivery.size)} knownDeliveryIds=${JSON.stringify([...managedAutomationByDelivery.keys()].slice(0, 10))}`);
        return undefined;
    }
    if (entry.expiresAt <= Date.now()) {
        console.info(`[bdk] hosted managedAutomation lookup expired deliveryId=${deliveryId} automationUuid=${entry.managedAutomation.automationUuid} expiredMsAgo=${String(Date.now() - entry.expiresAt)}`);
        managedAutomationByDelivery.delete(deliveryId);
        return undefined;
    }
    return entry.managedAutomation;
}
/** Drop recorded managed-automation slices (tests only). */
export function resetHostedManagedAutomationForTest() {
    managedAutomationTable().clear();
}
